from typing import List

class Solution:
    def combinationSum4(self, nums: List[int], target: int) -> int:
        def dfs(rem: int) -> int:
            if rem == 0:
                return 1
            if rem < 0:
                return 0
            return sum(dfs(rem - num) for num in nums)

        return dfs(target)

