from typing import List

class Solution:
    def combinationSum4(self, nums: List[int], target: int) -> int:
        memo = {0: 1}

        def dfs(rem: int) -> int:
            if rem < 0:
                return 0
            if rem not in memo:
                memo[rem] = sum(dfs(rem - num) for num in nums)
            return memo[rem]

        return dfs(target)

